
import type { DeliveryEligibilityMismatch } from './DeliveryEligibilityMismatch.js';

export type DeliveryMerchantDiagnostic = { /** Stable reason the method did not produce an option. - `ELIGIBILITY_NO_MATCH`: The configured eligibility expression excluded the method. - `METHOD_UNAVAILABLE`: The method was unavailable for this evaluation. - `INPUT_REQUIRED`: More typed buyer or caller input is required. - `CHECKOUT_CONTEXT_REQUIRED`: Exact evaluation requires a checkout session. - `PREVIEW_UNSUPPORTED`: The method cannot be evaluated in an orderless preview. - `DEPENDENCY_FAILURE`: A dependency prevented Flint from proving availability. */ "code": "ELIGIBILITY_NO_MATCH" | "METHOD_UNAVAILABLE" | "INPUT_REQUIRED" | "CHECKOUT_CONTEXT_REQUIRED" | "PREVIEW_UNSUPPORTED" | "DEPENDENCY_FAILURE" | (string & {}); "delivery_method_id"?: string; "delivery_method_revision_id"?: string; "diagnostic_id": string; /** Configured eligibility predicates that conclusively rejected the method. Present only for eligibility_no_match. */ "eligibility_mismatches"?: Array<DeliveryEligibilityMismatch>; /** RFC3339 timestamp. Format: date-time. */ "occurred_at": string; "outcome": "unavailable" | "input_required" | "cannot_calculate" | "requires_checkout_context" | "unsupported_in_preview" | (string & {}); "recommended_action": "review_configuration" | "provide_input" | "create_checkout" | "retry" | (string & {}); "retryable": boolean; "scope": "method" | (string & {}); "summary": string; };
